import{_ as a,c as i,o as t,af as n}from"./chunks/framework.BKeRpnBD.js";const m=JSON.parse('{"title":"Classical References","description":"Classical References，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"Classical References","description":"Classical References，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"en/articles/references/index.md","filePath":"en/articles/references/index.md"}'),s={name:"en/articles/references/index.md"};function r(o,e,h,l,d,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="takashima-ekidan-高島易断" tabindex="-1">Takashima Ekidan (高島易断) <a class="header-anchor" href="#takashima-ekidan-高島易断" aria-label="Permalink to “Takashima Ekidan (高島易断)”">​</a></h1><p><strong>Takashima Ekidan</strong> is a well-known Japanese work on I Ching divination from the Meiji era. Its author is commonly known as <strong>Takashima Tonsō</strong> (1832–1914), whose personal name is often given as <strong>Takashima Kaemon</strong>.</p><h2 id="takashima-and-the-i-ching-the-storyline" tabindex="-1">Takashima and the I Ching: the storyline <a class="header-anchor" href="#takashima-and-the-i-ching-the-storyline" aria-label="Permalink to “Takashima and the I Ching: the storyline”">​</a></h2><p>The <strong>I Ching (Zhouyi)</strong> formed in ancient China: tradition attributes the trigrams to Fuxi, the hexagrams and line statements to King Wen and the Duke of Zhou, and the later commentarial tradition to Confucius and subsequent scholars. Over time, it became both a philosophical classic and a practical method for divination.</p><p>Accounts of Takashima Tonsō often begin with a sharp turn: he was once <strong>imprisoned</strong>, and in prison he is said to have found a copy of the <strong>I Ching</strong>. With nothing else to do and everything to lose, he studied it obsessively—treating the text not as superstition, but as a way to read situations, weigh danger, and choose a line of action.</p><p>One popular episode tells of an attempted prison break. Takashima reportedly cast a reading of <strong>Treading → The Well (履之井)</strong>: a moment like “stepping on a tiger’s tail,” perilous but not necessarily fatal, with a narrow means of escape like a well-rope. When chaos erupted, he survived by hiding and moving along a rope used for hanging clothes—later seeing in that rope the very image of “The Well.”</p><p>After release, he moved to <strong>Yokohama</strong>, where he became both an entrepreneur and a diviner. He is remembered for applying the I Ching to practical decisions—whether to advance or stop, buy or sell, join or separate—while also providing readings for people of many stations, including public matters of the era. Those cases, and the method of tying judgments back to <strong>images, Judgement, and line statements</strong>, are what make <em>Takashima Ekidan</em> a durable study text.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to “Why it matters”">​</a></h2><ul><li>Practical examples that show how to take a line and make a judgment</li><li>A reading style that connects classical wording to real-world situations</li><li>A large collection of cases that can be compared and studied</li></ul><h2 id="what-this-app-includes-by-hexagram" tabindex="-1">What this app includes (by hexagram) <a class="header-anchor" href="#what-this-app-includes-by-hexagram" aria-label="Permalink to “What this app includes (by hexagram)”">​</a></h2><ul><li><strong>Name Reading</strong>: an entry-point explanation of the hexagram name and structure</li><li><strong>Judgement / Image</strong>: key text aligned to the classic</li><li><strong>Divination (占断)</strong>: concise Takashima-style readings for each hexagram</li><li><strong>Line-change details</strong>: per-line interpretations and curated cases</li></ul><p>This material is provided for study and reference. The original text is in the public domain.</p><hr><h1 id="jiao-s-yi-lin" tabindex="-1">Jiao&#39;s Yi Lin <a class="header-anchor" href="#jiao-s-yi-lin" aria-label="Permalink to “Jiao&#39;s Yi Lin”">​</a></h1><p>Jiao’s <strong>Yi Lin</strong> (also known as <em>Yi Lin</em>) is a Han-era, verse-based companion to I Ching divination. It is traditionally attributed to the Western Han scholar <strong>Jiao Yanshou</strong>, though the authorship is discussed in later sources.</p><p>Built on the 64 hexagrams of the <strong>Zhouyi</strong>, it systematizes readings by the pair <strong>Original hexagram → Changed hexagram</strong>: each original hexagram “branches” into 64 outcomes, producing <strong>64×64 = 4096</strong> short divinatory verses—often in a compact, rhymed style.</p><h2 id="the-storyline-with-the-i-ching" tabindex="-1">The storyline with the I Ching <a class="header-anchor" href="#the-storyline-with-the-i-ching" aria-label="Permalink to “The storyline with the I Ching”">​</a></h2><p>The I Ching provides a classical structure of images and line statements. <em>Yi Lin</em> adds a different layer: it turns hexagram meaning into vivid <strong>imagery and situations</strong>, making it easier to connect a cast to concrete life contexts.</p><h2 id="how-this-app-uses-yi-lin" tabindex="-1">How this app uses Yi Lin <a class="header-anchor" href="#how-this-app-uses-yi-lin" aria-label="Permalink to “How this app uses Yi Lin”">​</a></h2><p>For a cast, the app looks up the verse for <strong>Original → Changed</strong> and displays it as an aid:</p><ol><li>Identify key images (people, actions, places, objects, fortune words)</li><li>Map them to your question and real situation</li><li>Return to the hexagram and moving lines for the final judgment</li></ol><h2 id="translation-note" tabindex="-1">Translation note <a class="header-anchor" href="#translation-note" aria-label="Permalink to “Translation note”">​</a></h2><p>The English verses are derived from the Chinese text and lean toward literal rendering. The Chinese is the primary reference; English is provided for convenience.</p>',23)])])}const p=a(s,[["render",r]]);export{m as __pageData,p as default};
